def transform(grid):
    h, w = len(grid), len(grid[0])
    # The divider is the solid row or column separating the two regions.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and h > 1:
            region = grid[:r]
            break
    else:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)):
                region = [row[:c] for row in grid]
                break

    from collections import Counter
    counts = Counter(v for row in region for v in row)
    marker = min(counts, key=counts.get)
    background = max(counts, key=counts.get)
    return [[3 if v == marker else background for v in row] for row in region]
