    # A solid separator row: compare the regions above and below it.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            a, b = grid[:r], grid[r + 1:]
            return [[3 if x == y else 4 for x, y in zip(ra, rb)]
                    for ra, rb in zip(a, b)]

