def transform(grid):
    h, w = len(grid), len(grid[0])

    sep = next((c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1), None)
    if sep is not None:
        panel = [row[:sep] for row in grid]
        other = [row[sep + 1:] for row in grid]
    else:
        sep = next(r for r, row in enumerate(grid) if len(set(row)) == 1)
        panel, other = grid[:sep], grid[sep + 1:]

    shared = ({x for row in panel for x in row}
              & {x for row in other for x in row})
    background = next(iter(shared))
    return [[background if x == background else 3 for x in row]
            for row in panel]
